'use strict';
const PROFILE_PREFIX='ai-learning-profile-v1:';
let PROFILE_NAME='';
try{PROFILE_NAME=sessionStorage.getItem('ai-learning-active')||'';}catch(e){}
function profileEscape(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function profileScreen(){document.querySelector('#app').innerHTML=`<main class="profile-screen"><div class="card"><span class="tag">AWS AI Practitioner</span><h1>Your personal learning space</h1><p>Enter a username to start or resume your progress on this browser.</p><form id="profile-form"><label for="profile-name">Username</label><input id="profile-name" required minlength="2" maxlength="30" pattern="[A-Za-z0-9_-]{2,30}" autocomplete="username" placeholder="e.g. alex"><button class="btn" type="submit">Continue</button></form><p class="small muted">No password or database. A username is a local profile, not a secure account. Anyone using this browser can open a profile by entering its name. On another device, import your progress backup.</p><p id="profile-error" role="alert"></p></div></main>`;document.querySelector('#profile-form').onsubmit=e=>{e.preventDefault();const name=document.querySelector('#profile-name').value.trim().toLowerCase();if(!/^[a-z0-9_-]{2,30}$/.test(name))return;try{localStorage.setItem('ai-learning-storage-check','1');localStorage.removeItem('ai-learning-storage-check');sessionStorage.setItem('ai-learning-active',name);location.reload();}catch(e){document.querySelector('#profile-error').textContent='Browser storage is blocked. Enable site storage to save progress.';}};}
function profilePanel(){pause();const history=state.activity||[];document.querySelector('#profile-panel')?.remove();const panel=document.createElement('dialog');panel.id='profile-panel';panel.innerHTML=`<h2>Profile: ${profileEscape(PROFILE_NAME)}</h2><p>Progress saves automatically on this browser. Export a backup before clearing browser data or moving devices.</p><div class="flex"><button class="btn" id="export-profile">Export progress</button><label class="btn secondary">Import progress<input type="file" accept="application/json,.json" id="import-profile"></label><button class="btn secondary" id="switch-profile">Switch username</button><button class="btn secondary" id="close-profile">Close</button></div><p id="import-status" role="status"></p><h3>Recent activity</h3>${history.length?history.slice().reverse().map(x=>`<p><strong>${profileEscape(x.label)}</strong><br><small>${profileEscape(new Date(x.at).toLocaleString())}</small></p>`).join(''):'<p>Complete a lesson or test to see your activity here.</p>'}`;document.body.appendChild(panel);panel.showModal();document.querySelector('#close-profile').onclick=()=>panel.close();panel.addEventListener('close',()=>{panel.remove();render();});document.querySelector('#switch-profile').onclick=()=>{save();sessionStorage.removeItem('ai-learning-active');location.reload();};document.querySelector('#export-profile').onclick=()=>{save();const blob=new Blob([JSON.stringify({format:'ai-learning-profile',version:1,username:PROFILE_NAME,state},null,2)],{type:'application/json'});const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=PROFILE_NAME+'-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);};document.querySelector('#import-profile').onchange=async e=>{const status=document.querySelector('#import-status');try{const f=e.target.files[0];if(!f)return;if(f.size>5000000)throw Error('File is too large.');const raw=JSON.parse(await f.text());if(raw.format!=='ai-learning-profile'||raw.version!==1)throw Error('Choose a progress export from this app.');const next=cleanProfile(raw.state);if(!confirm('Replace progress for '+PROFILE_NAME+' with this backup?'))return;state=next;save();status.textContent='Progress imported. Close this panel to continue.';}catch(err){status.textContent='Import failed: '+err.message;}};}
function cleanProfile(raw){if(!raw||typeof raw!=='object'||!raw.attempts||!Array.isArray(raw.learned))throw Error('Invalid progress data.');const out={attempts:{},learned:raw.learned.filter(x=>DATA.concepts.some(c=>c.id===x)),settings:{mode:raw.settings?.mode==='exam'?'exam':'study',minutes:raw.settings?.minutes===90?90:120},activity:[]};for(const t of DATA.tests){const a=raw.attempts[t.id];if(!a)continue;const b={answers:{},seen:{},flags:{},revealed:{},index:Number.isInteger(a.index)?Math.max(0,Math.min(64,a.index)):0,mode:a.mode==='exam'?'exam':'study',remaining:Number.isFinite(a.remaining)?Math.max(0,Math.min(7200,a.remaining)):7200,runningSince:null,finished:a.finished===true};for(const q of t.questions){const v=a.answers?.[q.id];if(Array.isArray(v)&&v.length<=q.options.length&&v.every(n=>Number.isInteger(n)&&n>=-1&&n<q.options.length))b.answers[q.id]=v;b.seen[q.id]=a.seen?.[q.id]===true;b.flags[q.id]=a.flags?.[q.id]===true;}for(const k of ['startedAt','finishedAt'])if(typeof a[k]==='string')b[k]=a[k].slice(0,50);out.attempts[t.id]=b;}if(Array.isArray(raw.activity))out.activity=raw.activity.filter(x=>x&&typeof x.label==='string'&&typeof x.at==='string').slice(-200).map(x=>({label:x.label.slice(0,200),at:x.at.slice(0,50)}));return out;}
function recordActivity(label){state.activity=state.activity||[];state.activity.push({label,at:new Date().toISOString()});state.activity=state.activity.slice(-200);}
document.addEventListener('click',e=>{if(e.target.closest('[data-profile-panel]'))profilePanel();});
